// execute 函数签名固定：input_json 进，output 出，返回 OK 或 ERROR
int tool_set_face_execute(const char* input_json, char* output, size_t output_size)
{
    // 1. 解析输入参数
    char face_id[32] = "face_standby";  // 默认值
    int  duration_ms = 10000;           // 默认 10 秒

    cJSON* root = cJSON_Parse(input_json);
    if (root) {
        cJSON* f = cJSON_GetObjectItem(root, "face_id");
        cJSON* d = cJSON_GetObjectItem(root, "duration_ms");
        if (f && cJSON_IsString(f))  strncpy(face_id, f->valuestring, sizeof(face_id)-1);
        if (d && cJSON_IsNumber(d))  duration_ms = (int)d->valuedouble;
        cJSON_Delete(root);
    }

    // 2. 校验 face_id 是否在预置列表中
    static const char* valid[] = {
        "face_standby", "face_listening", "face_smile", "face_caring", /*...*/
        NULL
    };
    bool valid_id = false;
    for (int i = 0; valid[i]; i++) {
        if (strcmp(face_id, valid[i]) == 0) { valid_id = true; break; }
    }
    if (!valid_id) {
        snprintf(output, output_size, "{\"error\":\"invalid face_id: %s\"}", face_id);
        return ERROR;
    }

    // 3. 执行硬件操作（真机上调用 LVGL/屏幕驱动）
