// 在 tool_registry_init() 中添加，放在 vibrate 旁边：
REGISTER_TOOL(
    "set_face",                                          // Tool 名称（LLM 看到的名字）
    "Set device facial expression. face_id must be one of the preset IDs.", // 描述
    TOOL_SCHEMA_BEGIN()                                  // JSON Schema 开始
        TOOL_PARAM_STR("face_id", "Preset face resource ID. Valid: face_standby, face_smile, face_caring, face_comfort, face_calm, face_heart_breathing, face_energy_pulse, face_sleep_breathing, face_shy, face_thinking, face_waiting, face_muted, face_success, face_sleep, face_confused, face_error")
        ","                                              // ← 多个参数用逗号分隔
        TOOL_PARAM_NUM("duration_ms", "Duration in ms before reverting to default (max 10000)")
    TOOL_SCHEMA_END_REQUIRED("\"face_id\""),             // 必填参数列表
    tool_set_face_execute);                              // 执行函数指针
```

